import sys

class Solution:
    def minOperationsToFlip(self, expression: str) -> int:
        sys.setrecursionlimit(300000)
        n = len(expression)
        match = [0] * n
        st = []
        for i, ch in enumerate(expression):
            if ch == '(':
                st.append(i)
            elif ch == ')':
                j = st.pop()
                match[i] = j
                match[j] = i

        def ev(op, x, y):
            return x & y if op == '&' else x | y

        def combine(op, va, ca, vb, cb):
            goal = ev(op, va, vb) ^ 1
            best = float('inf')
            for na, wa in ((va, 0), (va ^ 1, ca)):
                for nb, wb in ((vb, 0), (vb ^ 1, cb)):
                    for no, wo in ((op, 0), ('|' if op == '&' else '&', 1)):
                        if ev(no, na, nb) == goal:
                            best = min(best, wa + wb + wo)
            return best

        def solve(lo, hi):
            if lo == hi:
                v = int(expression[lo])
                return v, 1
            if match[lo] == hi:
                return solve(lo + 1, hi - 1)
            mid, depth = lo, 0
            for i in range(lo, hi + 1):
                ch = expression[i]
                if ch == '(':
                    depth += 1
                elif ch == ')':
                    depth -= 1
                elif depth == 0 and ch in '&|':
                    mid = i
            va, ca = solve(lo, mid - 1)
            vb, cb = solve(mid + 1, hi)
            op = expression[mid]
            return ev(op, va, vb), combine(op, va, ca, vb, cb)

        return solve(0, n - 1)[1]

