class Solution {
public:
    int minOperationsToFlip(string expression) {
        e = expression;
        int n = e.size();
        match.assign(n, 0);
        vector<int> st;
        for (int i = 0; i < n; ++i) {
            if (e[i] == '(') st.push_back(i);
            else if (e[i] == ')') {
                int j = st.back(); st.pop_back();
                match[i] = j; match[j] = i;
            }
        }
        return solve(0, n - 1).second;
    }

private:
    string e;
    vector<int> match;

    int ev(char op, int x, int y) { return op == '&' ? x & y : x | y; }

    int combine(char op, int va, int ca, int vb, int cb) {
        int goal = ev(op, va, vb) ^ 1;
        int best = INT_MAX;
        int xs[2] = {va, va ^ 1}, wx[2] = {0, ca};
        int ys[2] = {vb, vb ^ 1}, wy[2] = {0, cb};
        char os[2] = {op, op == '&' ? '|' : '&'};
        for (int i = 0; i < 2; ++i)
            for (int j = 0; j < 2; ++j)
                for (int k = 0; k < 2; ++k) {
                    int nv = ev(os[k], xs[i], ys[j]);
                    int w = wx[i] + wy[j] + (k == 1);
                    if (nv == goal) best = min(best, w);
                }
        return best;
    }

    pair<int, int> solve(int lo, int hi) {
        if (lo == hi) return {e[lo] - '0', 1};
        if (match[lo] == hi) return solve(lo + 1, hi - 1);
        int mid = lo, depth = 0;
        for (int i = lo; i <= hi; ++i) {
            if (e[i] == '(') ++depth;
            else if (e[i] == ')') --depth;
            else if (depth == 0 && (e[i] == '&' || e[i] == '|')) mid = i;
        }
        auto [va, ca] = solve(lo, mid - 1);
        auto [vb, cb] = solve(mid + 1, hi);
        char op = e[mid];
        return {ev(op, va, vb), combine(op, va, ca, vb, cb)};
    }
};

