class Solution {
    private String e;
    private int[] match;

    public int minOperationsToFlip(String expression) {
        e = expression;
        int n = e.length();
        match = new int[n];
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (e.charAt(i) == '(') st.push(i);
            else if (e.charAt(i) == ')') {
                int j = st.pop();
                match[i] = j; match[j] = i;
            }
        }
        return solve(0, n - 1)[1];
    }

    private int ev(char op, int x, int y) { return op == '&' ? x & y : x | y; }

    private int combine(char op, int va, int ca, int vb, int cb) {
        int goal = ev(op, va, vb) ^ 1;
        int best = Integer.MAX_VALUE;
        int[] xs = {va, va ^ 1}, wx = {0, ca};
        int[] ys = {vb, vb ^ 1}, wy = {0, cb};
        char[] os = {op, op == '&' ? '|' : '&'};
        for (int i = 0; i < 2; i++)
            for (int j = 0; j < 2; j++)
                for (int k = 0; k < 2; k++) {
                    int nv = ev(os[k], xs[i], ys[j]);
                    int w = wx[i] + wy[j] + (k == 1 ? 1 : 0);
                    if (nv == goal) best = Math.min(best, w);
                }
        return best;
    }

    private int[] solve(int lo, int hi) {
        if (lo == hi) return new int[]{e.charAt(lo) - '0', 1};
        if (match[lo] == hi) return solve(lo + 1, hi - 1);
        int mid = lo, depth = 0;
        for (int i = lo; i <= hi; i++) {
            char ch = e.charAt(i);
            if (ch == '(') depth++;
            else if (ch == ')') depth--;
            else if (depth == 0 && (ch == '&' || ch == '|')) mid = i;
        }
        int[] a = solve(lo, mid - 1), b = solve(mid + 1, hi);
        char op = e.charAt(mid);
        return new int[]{ev(op, a[0], b[0]), combine(op, a[0], a[1], b[0], b[1])};
    }
}

