                o = min(a[1] + b[1], 1 + min(a[1], b[1]))
            else:
                o = min(a[1], b[1], 1 + a[1] + b[1])
                z = min(a[0] + b[0], 1 + min(a[0], b[0]))
            vals.append((z, o))

        for ch in expression:
            if ch == '(':
                ops.append(ch)
            elif ch == '&' or ch == '|':
                while ops and ops[-1] != '(':
                    fold()
                ops.append(ch)
            elif ch == ')':
