class Solution {
public:
    int minOperationsToFlip(string expression) {
        vector<pair<int,int>> vals;
        vector<char> ops;
        auto fold = [&]() {
            auto b = vals.back(); vals.pop_back();
            auto a = vals.back(); vals.pop_back();
            char op = ops.back(); ops.pop_back();
            int z, o;
            if (op == '&') {
                z = min({a.first, b.first, 1 + a.first + b.first});
                o = min(a.second + b.second, 1 + min(a.second, b.second));
            } else {
                o = min({a.second, b.second, 1 + a.second + b.second});
                z = min(a.first + b.first, 1 + min(a.first, b.first));
            }
            vals.push_back({z, o});
        };
        for (char ch : expression) {
            if (ch == '(') {
                ops.push_back(ch);
            } else if (ch == '&' || ch == '|') {
                while (!ops.empty() && ops.back() != '(') fold();
                ops.push_back(ch);
            } else if (ch == ')') {
                while (ops.back() != '(') fold();
                ops.pop_back();
            } else {
                int v = ch - '0';
                vals.push_back({v, v ^ 1});
            }
        }
        while (!ops.empty()) fold();
        return max(vals.back().first, vals.back().second);
    }
};

