class Solution {
    public int minOperationsToFlip(String expression) {
        Deque<int[]> vals = new ArrayDeque<>();
        Deque<Character> ops = new ArrayDeque<>();
        for (char ch : expression.toCharArray()) {
            if (ch == '(') {
                ops.push(ch);
            } else if (ch == '&' || ch == '|') {
                while (!ops.isEmpty() && ops.peek() != '(') fold(vals, ops);
                ops.push(ch);
            } else if (ch == ')') {
                while (ops.peek() != '(') fold(vals, ops);
                ops.pop();
            } else {
                int v = ch - '0';
                vals.push(new int[]{v, v ^ 1});
            }
        }
        while (!ops.isEmpty()) fold(vals, ops);
        int[] top = vals.pop();
        return Math.max(top[0], top[1]);
    }

    private void fold(Deque<int[]> vals, Deque<Character> ops) {
        int[] b = vals.pop(), a = vals.pop();
        char op = ops.pop();
        int z, o;
        if (op == '&') {
            z = Math.min(Math.min(a[0], b[0]), 1 + a[0] + b[0]);
            o = Math.min(a[1] + b[1], 1 + Math.min(a[1], b[1]));
        } else {
            o = Math.min(Math.min(a[1], b[1]), 1 + a[1] + b[1]);
            z = Math.min(a[0] + b[0], 1 + Math.min(a[0], b[0]));
        }
        vals.push(new int[]{z, o});
    }
}

